styles:
:root {
  --bg: #12121e; --surface: #1e1e32; --card: rgba(30, 30, 50, 0.85);
  --border: #3a3a5a; --yellow: #FFD93D; --orange: #FF6B35;
  --green: #6BCB77; --blue: #4D96FF; --pink: #FF6B9D;
  --purple: #C77DFF; --cyan: #00D4FF; --white: #F5F5F5; --muted: #8888AA;
}
* { box-sizing: border-box; margin: 0; padding: 0; }
body { font-family: 'Nanum Gothic', sans-serif; background: var(--bg); color: var(--white); min-height: 100vh; overflow-x: hidden; touch-action: manipulation; }

/* 🎮 민수 아케이드 네온 테마 (theme--arcade) */
body.theme--arcade {
  --bg: #12121e; --surface: #1e1e32; --card: rgba(30, 30, 50, 0.85);
  --border: #3a3a5a; --yellow: #FFD93D; --orange: #FF6B35;
  --green: #6BCB77; --blue: #4D96FF; --pink: #FF6B9D;
  --purple: #C77DFF; --cyan: #00D4FF; --white: #F5F5F5; --muted: #8888AA;
}

/* 🎠 민서 동화 밀키스 테마 (theme--slime) */
body.theme--slime {
  --bg: #fff3f5; --surface: #ffe7ee; --card: rgba(255, 255, 255, 0.95);
  --border: #ffb3c6; --yellow: #FFD93D; --orange: #FF6B35;
  --green: #6BCB77; --blue: #ff6b9d; --pink: #ff6b9d;
  --purple: #ff80ab; --cyan: #ff6b9d; --white: #4a3352; --muted: #8888AA;
}

/* 다크 테마 백그라운드 */
body.theme--arcade::before {
  content: ''; position: fixed; inset: 0;
  background-image: 
    radial-gradient(circle at 15% 50%, rgba(77, 150, 255, 0.08), transparent 25%),
    radial-gradient(circle at 85% 30%, rgba(199, 125, 255, 0.08), transparent 25%);
  pointer-events: none; z-index: 0;
}
body.theme--slime::before { display: none; }

.app-container { max-width: 1080px; margin: 0 auto; padding: 25px 16px; position: relative; z-index: 1; }

/* 🛠️ 상단 UI */
.top-bar { display: flex; justify-content: space-between; align-items: center; margin-bottom: 25px; }
.profile-badge { background: rgba(0,212,255,0.1); border: 2px solid var(--cyan); color: var(--cyan); padding: 8px 18px; border-radius: 30px; font-family: 'Jua', sans-serif; font-size: 1.2rem; }
.exit-btn { background: rgba(255,255,255,0.1); border: 2px solid var(--muted); color: var(--white); padding: 8px 18px; border-radius: 30px; font-family: 'Jua', sans-serif; font-size: 1.1rem; cursor: pointer; transition: 0.2s; }
.exit-btn:hover { background: rgba(255,107,53,0.2); border-color: var(--orange); color: var(--orange); }

/* 헤더 */
header { text-align: center; margin-bottom: 30px; }
.logo-title { font-family: 'Jua', sans-serif; font-size: 2.8rem; background: linear-gradient(135deg, var(--cyan), var(--purple), var(--pink)); -webkit-background-clip: text; -webkit-text-fill-color: transparent; margin-bottom: 8px; }
.sub-title { color: var(--muted); font-size: 1.05rem; }

/* 🚪 수학 메인 2대 대문 포털 카드 (Gateway Cards) */
.gateway-container {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 24px;
  margin: 30px 0;
}
.gateway-card {
  background: var(--card);
  border: 3px solid var(--border);
  border-radius: 28px;
  padding: 36px 24px;
  text-align: center;
  cursor: pointer;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  box-shadow: 0 10px 30px rgba(0,0,0,0.2);
  backdrop-filter: blur(12px);
  display: flex;
  flex-direction: column;
  align-items: center;
  text-decoration: none;
  position: relative;
  overflow: hidden;
}
.gateway-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0; height: 6px;
}
.gw-concepts::before { background: linear-gradient(90deg, #6BCB77, #00D4FF); }
.gw-workout::before { background: linear-gradient(90deg, #FF6B35, #FF6B9D); }
.gw-storybook::before { background: linear-gradient(90deg, #0284c7, #c084fc); }

.gateway-card:hover {
  transform: translateY(-8px) scale(1.02);
}
.gw-concepts:hover {
  border-color: var(--cyan);
  box-shadow: 0 15px 40px rgba(0, 212, 255, 0.3);
}
.gw-workout:hover {
  border-color: var(--orange);
  box-shadow: 0 15px 40px rgba(255, 107, 53, 0.3);
}
.gw-storybook:hover {
  border-color: #38bdf8;
  box-shadow: 0 15px 40px rgba(2, 132, 199, 0.4);
}

.gateway-icon { font-size: 4.8rem; margin-bottom: 16px; }
.gateway-title { font-family: 'Jua', sans-serif; font-size: 2rem; color: var(--white); margin-bottom: 12px; }
.gateway-desc { font-size: 1.05rem; color: var(--muted); line-height: 1.6; word-break: keep-all; margin-bottom: 20px; }

.gateway-badges {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: center;
}
.gateway-badge {
  font-family: 'Jua', sans-serif;
  font-size: 0.95rem;
  padding: 6px 14px;
  border-radius: 14px;
  background: rgba(255,255,255,0.08);
  color: var(--yellow);
  border: 1px solid var(--border);
}

/* 🧭 하위 뷰 내비게이션 바 */
.subview-nav {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
  background: var(--surface);
  padding: 12px 20px;
  border-radius: 20px;
  border: 2px solid var(--border);
}
.subview-title {
  font-family: 'Jua', sans-serif;
  font-size: 1.6rem;
  display: flex;
  align-items: center;
  gap: 10px;
}
.back-gate-btn {
  background: rgba(0, 212, 255, 0.15);
  border: 2px solid var(--cyan);
  color: var(--cyan);
  font-family: 'Jua', sans-serif;
  font-size: 1.1rem;
  padding: 6px 16px;
  border-radius: 20px;
  cursor: pointer;
  transition: 0.2s;
}
.back-gate-btn:hover {
  background: var(--cyan);
  color: #000;
}

/* 듀얼 보기 모드 스위처 (학년별 vs 영역별) */
.view-mode-switcher {
  display: flex;
  justify-content: center;
  gap: 10px;
  margin-bottom: 20px;
}
.mode-switch-btn {
  font-family: 'Jua', sans-serif;
  font-size: 1.2rem;
  padding: 10px 24px;
  border-radius: 24px;
  border: 2px solid var(--border);
  background: var(--surface);
  color: var(--muted);
  cursor: pointer;
  transition: all 0.2s ease;
}
.mode-switch-btn:hover { color: var(--white); border-color: var(--yellow); }
.mode-switch-btn.active {
  background: linear-gradient(135deg, var(--yellow), var(--orange));
  color: #12121e;
  border-color: transparent;
  font-weight: bold;
  box-shadow: 0 6px 18px rgba(255, 217, 61, 0.3);
}

/* 서브 필터 버튼 */
.filter-pill-bar {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-bottom: 25px;
  flex-wrap: wrap;
}
.filter-pill-btn {
  font-family: 'Jua', sans-serif;
  font-size: 1.05rem;
  padding: 8px 18px;
  border-radius: 20px;
  border: 1.5px solid var(--border);
  background: rgba(255,255,255,0.05);
  color: var(--muted);
  cursor: pointer;
  transition: all 0.2s ease;
}
.filter-pill-btn:hover, .filter-pill-btn.active {
  border-color: var(--cyan);
  background: rgba(0, 212, 255, 0.15);
  color: var(--cyan);
}

/* 섹션 타이틀 */
.sector-title { font-family: 'Jua', sans-serif; font-size: 1.5rem; margin-bottom: 16px; border-bottom: 2px dashed var(--border); padding-bottom: 8px; display: flex; align-items: center; gap: 8px; }
.sector-title.active-sector-12 { color: var(--green); }
.sector-title.active-sector-34 { color: var(--cyan); margin-top: 35px; }
.sector-title.active-sector-56 { color: #f59e0b; margin-top: 35px; }

.sector-title.topic-nat { color: var(--green); }
.sector-title.topic-frac { color: #ec4899; margin-top: 35px; }
.sector-title.topic-shape { color: var(--cyan); margin-top: 35px; }
.sector-title.topic-measure { color: var(--yellow); margin-top: 35px; }
.sector-title.active-sector-workout { color: #f43f5e; }

/* 그리드 & 카드 */
.mission-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 16px; }
.mission-card {
  background: var(--card);
  border: 2px solid var(--border);
  border-radius: 20px;
  padding: 22px 16px;
  text-align: center;
  cursor: pointer;
  transition: all 0.25s ease;
  text-decoration: none;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  min-height: 180px;
  box-shadow: 0 8px 20px rgba(0,0,0,0.15);
  backdrop-filter: blur(10px);
}

.mission-card:not(.disabled):hover { transform: translateY(-5px) scale(1.02); }
.mc-0:not(.disabled):hover { border-color: var(--pink); box-shadow: 0 10px 30px rgba(255, 107, 157, 0.25); }
.mc-1:not(.disabled):hover { border-color: var(--cyan); box-shadow: 0 10px 30px rgba(0, 212, 255, 0.2); }
.mc-2:not(.disabled):hover { border-color: var(--yellow); box-shadow: 0 10px 30px rgba(255, 217, 61, 0.2); }
.mc-3:not(.disabled):hover { border-color: #EC4899; box-shadow: 0 10px 30px rgba(236, 72, 153, 0.25); }
.mc-workout:not(.disabled):hover { border-color: #f43f5e; box-shadow: 0 10px 30px rgba(244, 63, 94, 0.3); }

.mission-icon { font-size: 3.2rem; margin-bottom: 12px; }
.mission-name { font-family: 'Jua', sans-serif; font-size: 1.45rem; color: var(--white); margin-bottom: 8px; }
.mission-desc { font-size: 0.95rem; color: var(--muted); line-height: 1.45; word-break: keep-all; }

/* 뷰 컨테이너 */
.view-container { display: none; }
.view-container.active { display: block; animation: fadeIn 0.25s ease; }

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: translateY(0); }
}

@media (max-width: 540px) {
  .gateway-container { grid-template-columns: 1fr; gap: 16px; }
  .gateway-card { padding: 26px 18px; }
  .gateway-icon { font-size: 3.8rem; }
  .gateway-title { font-size: 1.65rem; }
  .mission-grid { grid-template-columns: 1fr; gap: 12px; }
  .mission-card { min-height: auto; padding: 18px 14px; }
  .logo-title { font-size: 2.2rem; }
  .mode-switch-btn { font-size: 1.05rem; padding: 8px 16px; }
}

scripts:
window.currentSubject = "수학"; // 🚨 핵심: 전역 과목명 명시 (학습일지 및 보상 관제탑 연동)

// 🚪 수학 섹션 뷰 열기/닫기 (대문 <-> 개념관 <-> 트레이닝 센터)
function openMathSection(section) {
  const vGateway = document.getElementById('viewGateway');
  const vConcepts = document.getElementById('viewConcepts');
  const vWorkout = document.getElementById('viewWorkout');

  vGateway.classList.remove('active');
  vConcepts.classList.remove('active');
  vWorkout.classList.remove('active');

  if (section === 'concepts') {
    vConcepts.classList.add('active');
    window.location.hash = 'concepts';
  } else if (section === 'workout') {
    vWorkout.classList.add('active');
    window.location.hash = 'workout';
  } else {
    vGateway.classList.add('active');
    window.location.hash = '';
  }
  window.scrollTo({ top: 0, behavior: 'smooth' });
}

// 🔄 개념관 듀얼 뷰 스위치 (학년별 vs 영역별)
function switchConceptMode(mode) {
  const btnG = document.getElementById('btnModeGrade');
  const btnT = document.getElementById('btnModeTopic');
  const viewG = document.getElementById('conceptModeGrade');
  const viewT = document.getElementById('conceptModeTopic');

  if (mode === 'grade') {
    btnG.classList.add('active');
    btnT.classList.remove('active');
    viewG.style.display = 'block';
    viewT.style.display = 'none';
  } else {
    btnG.classList.remove('active');
    btnT.classList.add('active');
    viewG.style.display = 'none';
    viewT.style.display = 'block';
  }
}

// 🎯 학년 서브 필터링
function filterGradeSector(grade, btn) {
  document.querySelectorAll('#conceptModeGrade .filter-pill-btn').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');

  const s12 = document.getElementById('sector-block-12');
  const s34 = document.getElementById('sector-block-34');
  const s56 = document.getElementById('sector-block-56');

  if (grade === 'all') {
    s12.style.display = 'block';
    s34.style.display = 'block';
    s56.style.display = 'block';
  } else if (grade === '12') {
    s12.style.display = 'block';
    s34.style.display = 'none';
    s56.style.display = 'none';
  } else if (grade === '34') {
    s12.style.display = 'none';
    s34.style.display = 'block';
    s56.style.display = 'none';
  } else if (grade === '56') {
    s12.style.display = 'none';
    s34.style.display = 'none';
    s56.style.display = 'block';
  }
}

// 🎯 영역 서브 필터링
function filterTopicSector(topic, btn) {
  document.querySelectorAll('#conceptModeTopic .filter-pill-btn').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');

  const tNat = document.getElementById('topic-block-nat');
  const tFrac = document.getElementById('topic-block-frac');
  const tShape = document.getElementById('topic-block-shape');
  const tMeasure = document.getElementById('topic-block-measure');

  tNat.style.display = (topic === 'all' || topic === 'nat') ? 'block' : 'none';
  tFrac.style.display = (topic === 'all' || topic === 'frac') ? 'block' : 'none';
  tShape.style.display = (topic === 'all' || topic === 'shape') ? 'block' : 'none';
  tMeasure.style.display = (topic === 'all' || topic === 'measure') ? 'block' : 'none';
}

// 대문 이동 로직
document.getElementById('goLobbyBtn').addEventListener('click', () => {
    const activeChild = localStorage.getItem('currentChild') || (localStorage.getItem('currentUser') === 'daughter' ? 'minseo' : 'minsu');
    location.href = `../../../lobby.html?user=${activeChild}`;
});

// 초기 로드 시 해시 상태 또는 기본 대문 렌더링
document.addEventListener("DOMContentLoaded", () => {
  let currentProfile = localStorage.getItem('currentUser') || 'son';
  let currentChild = localStorage.getItem('currentChild') || (currentProfile === 'daughter' ? 'minseo' : 'minsu');
  const isDaughter = currentProfile === 'daughter' || currentChild === 'minseo';
  const name = isDaughter ? '민서' : (currentProfile === 'son' ? '민수' : '어른');
  const icon = isDaughter ? '👧' : (currentProfile === 'son' ? '👦' : '👨‍💻');

  const savedTheme = localStorage.getItem('currentTheme') || (isDaughter ? '슬라임' : '마인크래프트');
  const themeClass = savedTheme === '슬라임' ? 'theme--slime' : 'theme--arcade';
  document.body.className = themeClass;

  document.getElementById('userName').textContent = `${name} 대원`;
  document.getElementById('userIcon').textContent = icon;

  // URL 해시 확인
  function checkHashAndSwitch() {
    const hash = window.location.hash.replace('#', '');
    if (hash === 'concepts') {
      openMathSection('concepts');
    } else if (hash === 'workout') {
      openMathSection('workout');
    } else {
      openMathSection('gateway');
    }
  }
  checkHashAndSwitch();
  window.addEventListener('hashchange', checkHashAndSwitch);

  if (typeof initFairyAudio === 'function') initFairyAudio();
  if (typeof initFairyChat === 'function') initFairyChat("MATH", "수학관제탑");
  if (typeof updateTtsToggleUi === 'function') updateTtsToggleUi();
});
